import '../../src/style.css';
import '../../src/paper-theme.css';
import '../../src/own-cabinets.css';
import '../../src/ui/game-window.css';
import '../../src/ui/machine-game-layout.css';
import '../../src/ui/slot-game-layout.css';
import '../../src/ui/card-game-layout.css';
import { GameWindow } from '../../src/ui/GameWindow';
import { CardDealerStage } from '../../src/ui/CardDealerStage';
import { OriginalGames } from '../../src/ui/OriginalGames';
import { EZSlotsGame } from '../../src/ui/EZSlotsGame';
import { GithubGames } from '../../src/ui/GithubGames';
import { CasinoSessionsUI } from '../../src/ui/CasinoSessionsUI';
import { CasinoExpansionUI } from '../../src/ui/CasinoExpansionUI';
import { CasinoVariantsUI } from '../../src/ui/CasinoVariantsUI';
import { CasinoNextVariantsUI } from '../../src/ui/CasinoNextVariantsUI';
import { CasinoBatchVariantsUI } from '../../src/ui/CasinoBatchVariantsUI';
import { StudioGamesUI } from '../../src/ui/StudioGamesUI';
import { demoWallet } from '../../src/wallet/WalletClient';
import { expansionClient } from '../../src/wallet/ExpansionClient';
import { casinoClients } from '../../src/wallet/CasinoClient';
import { CABINETS } from '../../src/shared/cabinets';
import { VARIANT_GAMES, VARIANT_INFO, isVariantGame } from '../../src/shared/casinoVariants';
import { isBatchVariantGame } from '../../src/shared/casinoBatchVariants';
import { isNextVariantGame } from '../../src/shared/casinoNextVariants';
import { isExpansionGame } from '../../src/shared/casinoExpansion';
import { isSessionGame } from '../../src/shared/casinoSessions';
import { isGithubGame } from '../../src/shared/githubGames';
import { isStudioGame } from '../../src/shared/studioGames';
import { isCardGame } from '../../src/shared/cardTables';

const dialog = document.querySelector<HTMLDialogElement>('#mini-dialog')!;
const host = document.querySelector<HTMLElement>('#mini-game')!;
const dealerHost = document.querySelector<HTMLElement>('#card-dealer-stage')!;
new GameWindow(dialog);
let game: { destroy(): void } | undefined, dealer: CardDealerStage | undefined;
dialog.querySelector('[data-close]')!.addEventListener('click', () => dialog.close());
const account = new URL(location.href).searchParams.get('account') ?? 'window-preview';
demoWallet.setAccount(account); expansionClient.setAccount(account);
for (const client of Object.values(casinoClients)) client.setAccount(account);
const games = [...new Set([...CABINETS.filter(c => !c.demo && !c.provider).map(c => c.id), ...VARIANT_GAMES])];
function mount(id: string) {
  game?.destroy(); dealer?.destroy(); host.replaceChildren(); dealerHost.replaceChildren();
  dialog.classList.toggle('card-table-mode', isCardGame(id)); dialog.dataset.game = id;
  document.querySelector('#mini-title')!.textContent = CABINETS.find(c => c.id === id)?.name ?? (isVariantGame(id) ? VARIANT_INFO[id].name : id);
  dealerHost.hidden = !isCardGame(id);
  if (isCardGame(id)) dealer = new CardDealerStage(dealerHost, id, host);
  if (isBatchVariantGame(id)) game = new CasinoBatchVariantsUI(host, id);
  else if (isNextVariantGame(id)) game = new CasinoNextVariantsUI(host, id);
  else if (isVariantGame(id)) game = new CasinoVariantsUI(host, id);
  else if (isStudioGame(id)) game = new StudioGamesUI(host, id);
  else if (isExpansionGame(id)) game = new CasinoExpansionUI(host, id);
  else if (isSessionGame(id)) game = new CasinoSessionsUI(host, id);
  else if (isGithubGame(id)) game = new GithubGames(host, id);
  else if (id === 'royal-fruits') game = new EZSlotsGame(host);
  else game = new OriginalGames(host, id as ConstructorParameters<typeof OriginalGames>[1], { skipIntro: true });
  if (!dialog.open) dialog.showModal();
}
(window as any).windowPreview = { games, mount, demoWallet, expansionClient, casinoClients };
mount(new URL(location.href).searchParams.get('game') ?? 'variant-target-plinko');
